head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.checkcomboboxLabelCustom = function(selectedInfo, isOpen) {
    var ret = [];
    var separator = checkcombobox1.options.separator;
    var delimiter = checkcombobox1.options.delimiter;
    if (isOpen) {
        for (var i = 0; i < selectedInfo.length; i++) {
            ret.push(selectedInfo[i].value + delimiter + selectedInfo[i].label);
        }
    } else {
        for (var i = 0; i < selectedInfo.length; i++) {
            ret.push(selectedInfo[i].value);
        }
    }
    return ret.join(separator).wq_trim();
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#checkcombobox1_itemTable_1', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'checkcombobox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'checkcombobox1_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'checkcombobox1_label').innerText == '11'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
